window.AAP_SAMPLE = {"name": "SnapLedger (sample)", "files": {"LICENSE": {"text": "MIT License\n\nCopyright (c) 2026 SnapLedger Team\n"}, "README.md": {"text": "# SnapLedger\n\nSnap a photo of any receipt and SnapLedger turns it into a tidy expense entry.\nTrack monthly budgets, see where your money goes with simple charts, and get a gentle reminder when you are close to your limit.\n\n## Features\n- Scan paper receipts with the camera (on-device text recognition)\n- Automatic category suggestions (groceries, dining, transport, ...)\n- Monthly budget with progress bar and reminders\n- Category and 6-month reports\n- Sign in with Google to back up entries to the cloud\n- Works offline; syncs when online\n\n## Tech\nKotlin, Jetpack Compose, CameraX, ML Kit Text Recognition, Room, Firebase Auth/Firestore, Google Mobile Ads.\n\n## Contact\nSnapLedger Team · support@snapledger.example\n"}, "settings.gradle.kts": {"text": "rootProject.name = \"SnapLedger\"\ninclude(\":app\")\n"}, "app/build.gradle.kts": {"text": "plugins {\n    id(\"com.android.application\")\n    id(\"org.jetbrains.kotlin.android\")\n    id(\"com.google.gms.google-services\")\n}\n\nandroid {\n    namespace = \"com.sample.snapledger\"\n    compileSdk = 34\n\n    defaultConfig {\n        applicationId = \"com.sample.snapledger\"\n        minSdk = 24\n        targetSdk = 34\n        versionCode = 1\n        versionName = \"1.0.0\"\n    }\n\n    buildTypes {\n        release {\n            isMinifyEnabled = false\n            proguardFiles(getDefaultProguardFile(\"proguard-android-optimize.txt\"), \"proguard-rules.pro\")\n        }\n    }\n    buildFeatures { compose = true }\n}\n\ndependencies {\n    implementation(\"androidx.core:core-ktx:1.13.1\")\n    implementation(\"androidx.activity:activity-compose:1.9.0\")\n    implementation(\"androidx.camera:camera-camera2:1.3.4\")\n    implementation(\"androidx.camera:camera-view:1.3.4\")\n    implementation(\"com.google.mlkit:text-recognition:16.0.0\")\n    implementation(\"androidx.room:room-runtime:2.6.1\")\n    implementation(platform(\"com.google.firebase:firebase-bom:33.1.2\"))\n    implementation(\"com.google.firebase:firebase-auth\")\n    implementation(\"com.google.firebase:firebase-firestore\")\n    implementation(\"com.google.firebase:firebase-analytics\")\n    implementation(\"com.google.firebase:firebase-crashlytics\")\n    implementation(\"com.google.android.gms:play-services-auth:21.2.0\")\n    implementation(\"com.google.android.gms:play-services-ads:23.2.0\")\n}\n"}, "app/src/main/AndroidManifest.xml": {"text": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\">\n\n    <uses-permission android:name=\"android.permission.INTERNET\" />\n    <uses-permission android:name=\"android.permission.ACCESS_NETWORK_STATE\" />\n    <uses-permission android:name=\"android.permission.CAMERA\" />\n    <uses-permission android:name=\"android.permission.POST_NOTIFICATIONS\" />\n    <uses-permission android:name=\"android.permission.READ_MEDIA_IMAGES\" />\n    <uses-permission android:name=\"com.google.android.gms.permission.AD_ID\" />\n\n    <uses-feature android:name=\"android.hardware.camera\" android:required=\"false\" />\n\n    <application\n        android:name=\".SnapLedgerApp\"\n        android:allowBackup=\"true\"\n        android:icon=\"@mipmap/ic_launcher\"\n        android:label=\"@string/app_name\"\n        android:theme=\"@style/Theme.SnapLedger\"\n        android:usesCleartextTraffic=\"true\">\n\n        <meta-data\n            android:name=\"com.google.android.gms.ads.APPLICATION_ID\"\n            android:value=\"ca-app-pub-3940256099942544~3347511713\" />\n\n        <activity\n            android:name=\".MainActivity\"\n            android:exported=\"true\">\n            <intent-filter>\n                <action android:name=\"android.intent.action.MAIN\" />\n                <category android:name=\"android.intent.category.LAUNCHER\" />\n            </intent-filter>\n        </activity>\n        <activity android:name=\".ScanActivity\" android:exported=\"false\" />\n        <activity android:name=\".ReportActivity\" android:exported=\"false\" />\n        <activity android:name=\".LoginActivity\" android:exported=\"false\" />\n    </application>\n</manifest>\n"}, "app/src/main/ic_launcher-playstore.png": {"b64": ""}, "app/src/main/res/values/colors.xml": {"text": "<resources>\n    <color name=\"brand\">#FF107A68</color>\n    <color name=\"brand_dark\">#FF0B5C4F</color>\n    <color name=\"accent\">#FFFFC43D</color>\n</resources>\n"}, "app/src/main/res/values/strings.xml": {"text": "<resources>\n    <string name=\"app_name\">SnapLedger</string>\n    <string name=\"tagline\">Snap receipts, track spending</string>\n    <string name=\"home_title\">This month</string>\n    <string name=\"scan_title\">Scan receipt</string>\n    <string name=\"report_title\">Reports</string>\n    <string name=\"budget_label\">Monthly budget</string>\n    <string name=\"budget_warning\">You have used 80% of your budget</string>\n    <string name=\"sign_in_google\">Continue with Google</string>\n    <string name=\"category_groceries\">Groceries</string>\n    <string name=\"category_dining\">Dining</string>\n    <string name=\"category_transport\">Transport</string>\n    <string name=\"camera_rationale\">Camera access is needed to scan your receipts.</string>\n    <string name=\"notif_rationale\">Get a reminder before you go over budget.</string>\n</resources>\n"}, "app/src/main/res/mipmap-xxxhdpi/ic_launcher.png": {"b64": ""}, "app/src/main/res/values-th/strings.xml": {"text": "<resources>\n    <string name=\"app_name\">SnapLedger</string>\n    <string name=\"tagline\">ถ่ายใบเสร็จ จดรายจ่ายอัตโนมัติ</string>\n    <string name=\"home_title\">เดือนนี้</string>\n    <string name=\"scan_title\">สแกนใบเสร็จ</string>\n    <string name=\"report_title\">รายงาน</string>\n    <string name=\"budget_label\">งบประมาณรายเดือน</string>\n    <string name=\"budget_warning\">คุณใช้งบไปแล้ว 80%</string>\n    <string name=\"sign_in_google\">ดำเนินการต่อด้วย Google</string>\n    <string name=\"category_groceries\">ของใช้ในบ้าน</string>\n    <string name=\"category_dining\">ร้านอาหาร</string>\n    <string name=\"category_transport\">การเดินทาง</string>\n    <string name=\"camera_rationale\">ต้องใช้กล้องเพื่อสแกนใบเสร็จของคุณ</string>\n    <string name=\"notif_rationale\">แจ้งเตือนก่อนที่คุณจะใช้เงินเกินงบ</string>\n</resources>\n"}, "app/src/main/res/values-ko/strings.xml": {"text": "<resources>\n    <string name=\"app_name\">스냅가계부</string>\n    <string name=\"tagline\">영수증 찍으면 가계부 끝</string>\n    <string name=\"home_title\">이번 달</string>\n    <string name=\"scan_title\">영수증 스캔</string>\n    <string name=\"report_title\">리포트</string>\n    <string name=\"budget_label\">월 예산</string>\n    <string name=\"budget_warning\">예산의 80%를 썼어요</string>\n    <string name=\"sign_in_google\">Google로 계속하기</string>\n    <string name=\"category_groceries\">장보기</string>\n    <string name=\"category_dining\">외식</string>\n    <string name=\"category_transport\">교통</string>\n    <string name=\"camera_rationale\">영수증을 스캔하려면 카메라 권한이 필요해요.</string>\n    <string name=\"notif_rationale\">예산을 넘기기 전에 알려드릴게요.</string>\n</resources>\n"}, "ios/SnapLedger.xcodeproj/project.pbxproj": {"text": "/* excerpt of project.pbxproj */\nPRODUCT_BUNDLE_IDENTIFIER = com.sample.snapledger;\nMARKETING_VERSION = 1.0.0;\nCURRENT_PROJECT_VERSION = 1;\nIPHONEOS_DEPLOYMENT_TARGET = 15.0;\n"}, "ios/SnapLedger/Info.plist": {"text": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n<plist version=\"1.0\">\n<dict>\n    <key>CFBundleDisplayName</key>\n    <string>SnapLedger</string>\n    <key>CFBundleIdentifier</key>\n    <string>$(PRODUCT_BUNDLE_IDENTIFIER)</string>\n    <key>CFBundleShortVersionString</key>\n    <string>$(MARKETING_VERSION)</string>\n    <key>NSCameraUsageDescription</key>\n    <string>Camera access is needed to scan your receipts.</string>\n    <key>NSPhotoLibraryUsageDescription</key>\n    <string></string>\n    <key>GADApplicationIdentifier</key>\n    <string>ca-app-pub-3940256099942544~1458002511</string>\n</dict>\n</plist>\n"}, "screenshots/01-home.png": {"b64": ""}, "screenshots/02-scan.png": {"b64": ""}, "screenshots/03-reports.png": {"b64": ""}}};
